CREATE TABLE IF NOT EXISTS users (name VARCHAR(64) PRIMARY KEY,password VARCHAR(128) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login DATETIME NULL,last_logout DATETIME NULL);
CREATE TABLE IF NOT EXISTS audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,event TEXT);
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(36) PRIMARY KEY,username VARCHAR(64),remote_ip VARCHAR(128),protocol VARCHAR(16),connected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,disconnected_at DATETIME NULL,last_seen TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS history (id BIGINT AUTO_INCREMENT PRIMARY KEY,at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,url TEXT,method VARCHAR(16),status VARCHAR(128));
CREATE TABLE IF NOT EXISTS requests (id BIGINT AUTO_INCREMENT PRIMARY KEY,at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,method VARCHAR(16),target TEXT,remote_ip VARCHAR(128),status INT,bytes BIGINT,action VARCHAR(20) DEFAULT 'GET',session_id VARCHAR(36) NULL);

